  ctx.fillStyle = "#9a9a9a";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.font = canvasGlyphFont(glyph, '0.92px', 900);
  ctx.fillText(glyph, x, y + 0.01);
  ctx.restore();
}

