  const tooltips = [groundTip, stairTip, interactableTip, trapTip];
  for (const tip of tooltips) {
    if (tip === active) {
      tip.style.display = 'block';
      tip.style.zIndex = String(UI_TOOLTIP_Z_FOCUS);
