// --- Socket circles ---
const maxSockets = Number(it.maxSockets || 0) | 0;
if (maxSockets > 0) {
  const sockets = Array.isArray(it.sockets) ? it.sockets : [];
  const socketedGems = Array.isArray(it.socketedGems) ? it.socketedGems : [];
  const sockRow = document.createElement('div');
  sockRow.style.marginTop = '4px';
  sockRow.style.letterSpacing = '2px';
  sockRow.style.fontSize = '14px';
  let circles = '';
  for (let s = 0; s < maxSockets; s++) {
    circles += s < sockets.length ? '\u25C8' : '\u25CB'; // filled, empty
  }
  sockRow.textContent = `Sockets: ${circles}`;
  sockRow.style.color = '#c8a860';
  container.appendChild(sockRow);

  for (const gem of socketedGems) {
    const gemRow = document.createElement('div');
    Object.assign(gemRow.style, {
      display: 'flex',
      alignItems: 'flex-start',
      gap: '5px',
      marginTop: '2px',
      color: '#b8e6b8',
      fontSize: '12px',
    });
    const icon = document.createElement('span');
      const iconRef = resolveIconReference({ iconAtlas: 'items', iconId: gem?.iconId || '' });
      const hasIcon = applyAtlasIcon(icon, iconRef, '◆', 16);
    if (!hasIcon) icon.textContent = '◆';
    icon.style.color = '#8de0ff';
    icon.style.flex = '0 0 auto';
    gemRow.appendChild(icon);

    const text = document.createElement('span');
    const lines = Array.isArray(gem?.detailLines)
      ? gem.detailLines.map((line) => String(line || '').trim()).filter(Boolean)
      : [];
    const gemName = document.createElement('span');
    gemName.textContent = `${String(gem?.name || 'Gem')} — `;
    gemName.style.color = '#cfe8ff';
    gemName.style.fontWeight = 'bold';
    text.appendChild(gemName);
    if (lines.length) {
      lines.forEach((line, index) => {
        if (index > 0) text.appendChild(document.createTextNode(' '));
        const normalized = line.replace(/^Socketed:/i, 'Socket:').replace(/^On hit:/i, 'Equip:');
        const match = normalized.match(/^([^:]+):\s*(.*)$/);
        if (!match) {
          text.appendChild(document.createTextNode(normalized));
          return;
        }
        const label = document.createElement('span');
        label.textContent = `${match[1]}: `;
        label.style.color = '#d9ffd9';
        label.style.fontWeight = 'bold';
        text.appendChild(label);
        text.appendChild(document.createTextNode(match[2]));
      });
    } else {
      text.appendChild(document.createTextNode('socketed'));
    }
    gemRow.appendChild(text);
    container.appendChild(gemRow);
  }
}

