// display/camera/shake.js
// Procedural shake; visual-only

export function startShake(cam, amp = 3, dur = 0.25) {
  // Only override if new shake is stronger than remaining shake
  const remaining = cam._shakeDur ? (1 - cam._shakeTime / cam._shakeDur) * cam._shakeAmp : 0;
  if (amp < remaining) return;
  cam._shakeAmp = amp;
  cam._shakeDur = dur;
  cam._shakeTime = 0;
  cam._shakeSlam = false;
}

/**
 * Slam shake — one hard downward hit that snaps back.
 * Used for meteor impacts and other catastrophic events.
 */
export function startSlamShake(cam, amp = 14, dur = 0.45) {
  cam._shakeAmp = amp;
  cam._shakeDur = dur;
  cam._shakeTime = 0;
  cam._shakeSlam = true;
}

export function updateShake(cam, dt, rand = Math.random) {
  if (!cam._shakeDur) return;
  cam._shakeTime += dt;
  const k = cam._shakeTime / cam._shakeDur;
  if (k >= 1) {
    cam.shakeX = cam.shakeY = 0;
    cam._shakeDur = 0;
    cam._shakeSlam = false;
  } else if (cam._shakeSlam) {
    // Single hard downward slam with sharp exponential snap-back
    const hit = Math.exp(-k * 8) * cam._shakeAmp;
    cam.shakeX = (rand() - 0.5) * hit * 0.3;
    cam.shakeY = hit;
  } else {
    const fall = (1 - k) * cam._shakeAmp;
    cam.shakeX = (rand() - 0.5) * fall * 2;
    cam.shakeY = (rand() - 0.5) * fall * 2;
  }
}
// display/camera/zoomPunch.js
// Brief camera scale pulse on critical hits — "zoom punch".
// Snaps scale up by a small amount, then eases back to 1.0.
// Additive: applies on top of the camera's normal scale, just like shake.

/** Peak zoom boost (fraction above 1.0). 0.02 = 2% zoom-in. */
const PUNCH_PEAK = 0.02;

/** Duration of the full punch cycle (seconds of real time). */
const PUNCH_DURATION = 0.12;

/** Ease-out: time spent ramping back to 1.0 (as fraction of duration). */
const EASE_FRAC = 0.7;

export function startZoomPunch(cam, peak = PUNCH_PEAK, dur = PUNCH_DURATION) {
  cam._zpPeak = peak;
  cam._zpDur = dur;
  cam._zpTime = 0;
}

export function updateZoomPunch(cam, dt) {
  if (!cam._zpDur) return;
  cam._zpTime += dt;
  const k = cam._zpTime / cam._zpDur;
  if (k >= 1) {
    cam._zpScale = 0;
    cam._zpDur = 0;
    return;
  }
  const attackEnd = 1 - EASE_FRAC;
  let intensity;
  if (k < attackEnd) {
    // Snap up to peak
    intensity = k / attackEnd;
  } else {
    // Ease back to 0
    const t = (k - attackEnd) / EASE_FRAC;
    intensity = 1 - t * t; // quadratic ease-out
  }
  cam._zpScale = cam._zpPeak * intensity;
}

/** Get the additive scale offset to apply this frame. */
export function getZoomPunchScale(cam) {
  return cam._zpScale || 0;
}

