world.on("chest:burst", ({ actor, targetId, origin, drops }) => {
  const ox = Number(origin?.x || 0);
  const oy = Number(origin?.y || 0);
  if (Number.isFinite(ox) && Number.isFinite(oy)) {
    for (let i = 0; i < 18; i++) {
      const a = (Math.PI * 2 * i) / 18;
      const spd = 0.12 + (i % 3) * 0.03;
      fx.pool.spawn(new Particle({
        x: ox + Math.cos(a) * 0.12,
        y: oy + Math.sin(a) * 0.08,
        vx: Math.cos(a) * spd,
        vy: Math.sin(a) * spd - 0.04,
        ay: 0.06,
        life: 0.28 + (i % 4) * 0.04,
        size0: 0.05,
        size1: 0.018,
        r: 199,
        g: 125,
        b: 255,
        a0: 0.66,
      }));
    }
  }

  const burstDrops = Array.isArray(drops) ? drops : [];
  let bestBurstRank = 1;
  let bestBurstRarity = "common";
  for (let i = 0; i < burstDrops.length; i++) {
    const d = burstDrops[i];
    const itemId = Number(d?.itemId || 0) | 0;
    const atX = Number(d?.at?.x || 0);
    const atY = Number(d?.at?.y || 0);
    const info = world.get(itemId, ItemInfo);
    const color = lootRarityColorHex(info);
    const rarity = String(info?.rarityName || "common").toLowerCase();
    const rarityRank = rarity === "legendary" ? 5
      : rarity === "epic" ? 4
      : rarity === "rare" ? 3
      : rarity === "uncommon" ? 2 : 1;
    if (rarityRank > bestBurstRank) {
      bestBurstRank = rarityRank;
      bestBurstRarity = rarity;
    }
    const rgb = color.startsWith("#")
      ? {
        r: Number.parseInt(color.slice(1, 3), 16) || 255,
        g: Number.parseInt(color.slice(3, 5), 16) || 255,
        b: Number.parseInt(color.slice(5, 7), 16) || 255,
      }
      : { r: 255, g: 255, b: 255 };
    fx.pool.spawn(new Particle({
      x: atX,
      y: atY - 0.05,
      vx: 0,
      vy: -0.03,
      ay: -0.02,
      life: 0.22,
      size0: 0.055,
      size1: 0.014,
      r: rgb.r,
      g: rgb.g,
      b: rgb.b,
      a0: 0.62,
    }));

    // Gear gets a readable name reveal in addition to the world-space beam.
    // Delay each name by the same tiny cadence as the shafts so a multi-drop
    // chest reads as a sequence of discoveries instead of one noisy flash.
    if (info?.type === "equip" && ftext && rarityRank >= 2) {
      const dropName = resolveItemDisplayName(world, itemId);
      if (dropName) {
        ftext.addStatus(atX + 0.5, atY + 0.12, dropName, {
          color,
          life: 1.45,
          delay: 0.16 + i * 0.045,
          scaleStart: rarityRank >= 4 ? 1.22 : 1.06,
          scaleEnd: 0.94,
        });
      }
    }

    const height = rarity === 'legendary' ? 1.95
      : rarity === 'epic' ? 1.65
      : rarity === 'rare' ? 1.38
      : 1.02;
    _chestRevealBeams.push({
      x: atX + 0.5,
      y: atY + 0.5,
      age: -0.16 - i * 0.045,
      maxAge: 1.05 + Math.min(0.3, height * 0.12),
      height,
      color: [rgb.r, rgb.g, rgb.b],
      seed: itemId || i,
    });
    const sparkleCount = rarity === 'legendary' ? 10
      : rarity === 'epic' ? 8
      : rarity === 'rare' ? 6
      : 4;
    for (let s = 0; s < sparkleCount; s++) {
      const angle = (Math.PI * 2 * s) / sparkleCount + (itemId % 11) * 0.13;
      const speed = 0.10 + (s % 2) * 0.035;
      fx.pool.spawn(new Particle({
        x: atX + 0.5,
        y: atY + 0.5,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 0.05,
        ay: 0.06,
        life: 0.42 + (s % 3) * 0.06,
        size0: rarity === 'legendary' ? 0.07 : 0.05,
        size1: 0.012,
        r: Math.min(255, rgb.r + 35),
        g: Math.min(255, rgb.g + 35),
        b: Math.min(255, rgb.b + 35),
        a0: 0.82,
      }));
    }
  }

  const pe = playerEntity(world);
  if (!pe || pe.id !== (Number(actor) | 0)) return;
  if (bestBurstRank >= 4 && ftext) {
    const label = bestBurstRarity === "legendary" ? "LEGENDARY!" : "EPIC FIND!";
    const color = bestBurstRarity === "legendary" ? "#ff9a5a" : "#d58bff";
    ftext.addBanner(ox + 0.5, oy - 0.25, label, {
      color,
      delay: 0.34,
      life: 1.45,
      scaleStart: bestBurstRank === 5 ? 1.7 : 1.45,
      scaleEnd: 1.0,
    });
  }
  const chestName = String(world.get(Number(targetId) | 0, NamedIdentity)?.name || "chest").toLowerCase();
  try { messageLog.log({ text: `You crack open the ${chestName}. Loot spills out.`, type: "system" }); } catch {}
  if (DEBUG_DISABLE_LEGACY_FLOOR_PICKUP_TOOLTIP) {
    try { window.dispatchEvent(new CustomEvent("ui:hideGroundItem")); } catch {}
    try { window.dispatchEvent(new CustomEvent("ui:requestInventoryData")); } catch {}

  const deathVfx = createDeathVfxController();
  const teleportFx = createTeleportFxController({ world, cam, isPlayer });
  world.install(createPuffFxExtension({ fx }));

  // ── Melee camera shake — scales with damage ───────────────────────
  world.on('damaged', ({ cause, amount, critical }) => {
    if (cause !== 'melee') return;
    const dmg = Number(amount) || 0;
    if (dmg < 1) return;
    // Amplitude: 1.0 at 1dmg, ramps to ~5 at 15+dmg, crits get 1.4x
    const base = 1.0 + Math.min(4.0, Math.log(1 + dmg / 2.5) * 2.2);
    const amp = critical ? base * 1.4 : base;
    // Duration: 0.06s baseline, scales gently with damage
    const dur = 0.06 + Math.min(0.10, dmg * 0.004);
    startShake(cam, amp, dur);
    // Crit zoom-punch: brief scale pulse that sells the weight of a big hit
    if (critical) startZoomPunch(cam, 0.025, 0.14);
  });

  // Chest openings get a tiny physical payoff. Scale it from the best item so
  // a legendary reveal lands harder without turning ordinary loot into combat
  // noise. This is display-only camera feedback; the rules event is unchanged.
  world.on('chest:burst', ({ actor, drops }) => {
    if (!isPlayer(actor)) return;
    const burstDrops = Array.isArray(drops) ? drops : [];
    let bestRank = 1;
    for (let i = 0; i < burstDrops.length; i++) {
      const info = getItemInfo(Number(burstDrops[i]?.itemId || 0) | 0);
      const rarity = String(info?.rarityName || 'common').toLowerCase();
      const rank = rarity === 'legendary' ? 5
        : rarity === 'epic' ? 4
        : rarity === 'rare' ? 3
        : rarity === 'uncommon' ? 2 : 1;
      if (rank > bestRank) bestRank = rank;
    }
    startShake(cam, 1.15 + bestRank * 0.42, 0.08 + bestRank * 0.012);
    startZoomPunch(cam, 0.012 + bestRank * 0.003, 0.10 + bestRank * 0.012);
  });

  // The reward should land when the item reaches the player, not only when it
  // is first spotted. Rare+ pickups get a tiny ownership pulse; ordinary
  // pickups keep the existing loot-suck animation and audio unchanged.
  world.on('item:pickup', ({ actor, itemId }) => {
    if (!isPlayer(actor)) return;
    const info = getItemInfo(Number(itemId || 0) | 0);
    const rarity = String(info?.rarityName || 'common').toLowerCase();
    const rank = rarity === 'legendary' ? 5
      : rarity === 'epic' ? 4 : rarity === 'rare' ? 3 : 1;
    if (rank < 3) return;
    startZoomPunch(cam, 0.010 + rank * 0.002, 0.09 + rank * 0.01);
    if (rank >= 4) startShake(cam, 0.45 + rank * 0.08, 0.055);
  });

  const { goreTick } = installFloatTextWiring({ world, ftext, fx, getPosition, isVisibleAt, isPet, isPlayer, getFxTime });
  world.install(createFountainPresentationExtension({ ftext, fx, getPosition, isVisibleAt }));
  world.install(createFountainUiExtension({ getPlayerEntity, getItemInfo, resolveItemDisplayName }));
  installContentVfxWiring({ world, ftext, fx, getPosition, isVisibleAt });
  installEventUiWiring({
    world,
    ftext,
    getActiveSpellId,
    setActiveSpell,
    getPlayerEntity,
    getPosition,
    getItemInfo,
// display/camera/zoomPunch.js
// Brief camera scale pulse on critical hits — "zoom punch".
// Snaps scale up by a small amount, then eases back to 1.0.
// Additive: applies on top of the camera's normal scale, just like shake.

/** Peak zoom boost (fraction above 1.0). 0.02 = 2% zoom-in. */
const PUNCH_PEAK = 0.02;

/** Duration of the full punch cycle (seconds of real time). */
const PUNCH_DURATION = 0.12;

/** Ease-out: time spent ramping back to 1.0 (as fraction of duration). */
const EASE_FRAC = 0.7;

export function startZoomPunch(cam, peak = PUNCH_PEAK, dur = PUNCH_DURATION) {
  cam._zpPeak = peak;
  cam._zpDur = dur;
  cam._zpTime = 0;
}

export function updateZoomPunch(cam, dt) {
  if (!cam._zpDur) return;
  cam._zpTime += dt;
  const k = cam._zpTime / cam._zpDur;
  if (k >= 1) {
    cam._zpScale = 0;
    cam._zpDur = 0;
    return;
  }
  const attackEnd = 1 - EASE_FRAC;
  let intensity;
  if (k < attackEnd) {
    // Snap up to peak
    intensity = k / attackEnd;
  } else {
    // Ease back to 0
    const t = (k - attackEnd) / EASE_FRAC;
    intensity = 1 - t * t; // quadratic ease-out
  }
  cam._zpScale = cam._zpPeak * intensity;
}

/** Get the additive scale offset to apply this frame. */
export function getZoomPunchScale(cam) {
  return cam._zpScale || 0;
}

