function ensureTrapIdentity(world, trapId, t) {
  const ident = world.get(trapId, NamedIdentity);
  if (ident) return;
  const trapNames = {
    spike: "Spike Trap",
    snake: "Snake Trap",
    shock: "Shock Trap",
    pit: "Pit Trap",
    siphon: "Siphon Trap",
    rust: "Rust Trap",
    swarm: "Swarm Trap",
    arrow: "Arrow Trap",
